const raw = $input.first().json;

// Extract sender email from various formats
let emailFrom = '';
const from = raw.from || raw.From || '';
if (typeof from === 'string') {
  const match = from.match(/<([^>]+)>/);
  emailFrom = match ? match[1] : from;
} else if (from.value && from.value[0]) {
  emailFrom = from.value[0].address || '';
}

// Skip your own emails — add all your sending addresses here
if (emailFrom === '[YOUR_EMAIL]') return [];

const subject = raw.subject || raw.Subject || '(no subject)';
const snippet = raw.snippet || raw.textPlain || raw.text || '';
const messageId = raw.id || raw.messageId || '';

if (!emailFrom) return [];

return [{ json: { email_from: emailFrom.replace(/'/g, "''"), subject, snippet: snippet.substring(0, 500), message_id: messageId } }];

const raw = ($input.first().json?.choices?.[0]?.message?.content || '').trim();
const lead = $('Lookup Lead by Email').first().json;
const emailData = $('Extract Sender Email').first().json;

let parsed;
try {
  let cleaned = raw;
  if (cleaned.startsWith('`')) cleaned = cleaned.replace(/^`{3}json?\s*/, '').replace(/\s*`{3}$/, '').trim();
  const match = cleaned.match(/\{[\s\S]*\}/);
  if (match) parsed = JSON.parse(match[0]);
} catch(e) {}

if (!parsed) {
  parsed = { asunto: 'Re: ' + emailData.subject, cuerpo: '<p>' + raw.replace(/\n/g, '<br>') + '</p>' };
}

// Add your email signature HTML here
// Example: const firma = '<br><br><table>...</table>';
// Then append: parsed.cuerpo + firma
const firma = '';

function esc(v) { return String(v || '').replace(/'/g, "''"); }

return [{ json: {
  asunto: parsed.asunto,
  cuerpo_html: parsed.cuerpo + firma,
  email_destino: emailData.email_from,
  negocio: lead.negocio,
  pais: lead.pais || lead.pais_n || 'US',
  negocio_esc: esc(lead.negocio),
  email_esc: esc(emailData.email_from),
  pais_esc: esc(lead.pais || lead.pais_n || 'US'),
  asunto_esc: esc(parsed.asunto),
  cuerpo_esc: esc(parsed.cuerpo).substring(0, 2000),
  snippet_entrante: emailData.snippet.substring(0, 200)
} }];

const email = $input.first().json;
const mime = 'To: ' + email.email_destino + '\r\n' +
  'Subject: =?UTF-8?B?' + Buffer.from(email.asunto, 'utf-8').toString('base64') + '?=\r\n' +
  'Content-Type: text/html; charset=utf-8\r\n' +
  'MIME-Version: 1.0\r\n' +
  '\r\n' +
  email.cuerpo_html;
const raw = Buffer.from(mime, 'utf-8').toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
return [{ json: { ...email, raw_message: raw } }];
